    origen = -4.5;
    aceptado = redondear_entero(origen, destino);
    std::cout << "Moitié négative : " << aceptado << ";Destination : " << destino << '\n';
    origen = 100.0;
    aceptado = redondear_entero(origen, destino);
    std::cout << "Limite : " << aceptado << ";Destination : " << destino << '\n';
    origen = 100.25;
